package com.gymmind.membership.domain.model;
import com.gymmind.shared.persistence.TenantScopedEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="membership_package") public class MembershipPackage extends TenantScopedEntity { @Column(nullable=false,length=128) private String name; @Column(name="entitlement_type",nullable=false,length=16) private String entitlementType; @Column(name="entitlement_count") private Integer entitlementCount; @Column(name="valid_days") private Integer validDays; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Column(nullable=false,length=3) private String currency; @Column(nullable=false) private boolean active=true; protected MembershipPackage(){} private MembershipPackage(Long t,String n,String type,Integer count,Integer days,BigDecimal p,String c){super(t);if(n==null||n.isBlank()||type==null||type.isBlank()||p==null||p.signum()<0||c==null||c.length()!=3)throw new IllegalArgumentException("Invalid membership package");name=n.trim();entitlementType=type.trim();entitlementCount=count;validDays=days;price=p;currency=c.toUpperCase();} public static MembershipPackage create(Long t,String n,String type,Integer count,Integer days,BigDecimal p,String c){return new MembershipPackage(t,n,type,count,days,p,c);} public void disable(){active=false;} public String getName(){return name;} public String getEntitlementType(){return entitlementType;} public Integer getEntitlementCount(){return entitlementCount;} public Integer getValidDays(){return validDays;} public BigDecimal getPrice(){return price;} public String getCurrency(){return currency;} public boolean isActive(){return active;} }
